final SubmissionPublisher<State> states = new SubmissionPublisher<>();
private volatile State current = new State(false, null);

void dispatch(Event e) {
    State next = reduce(current, e);
    if (next.equals(current)) return;      // conflate equal states
    current = next;
    states.submit(next);                   // delivered per subscriber demand
}
State current() { return current; }        // Flow has no replay: expose it
